'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['projectFields']);
const { projectFields } = api;

const liveObject = { state: 1 };
const copiedObject = { nested: 2 };
const copiedArray = [1, { deep: true }];
const source = {
  first: copiedObject,
  live: liveObject,
  list: copiedArray,
  nil: null,
  count: 7,
  text: 'x'
};
const liveKeys = ['live'];
const result = projectFields(source, liveKeys);
assert.deepStrictEqual(Object.keys(result), Object.keys(source));
assert.notStrictEqual(result, source);
assert.strictEqual(result.live, liveObject);
assert.notStrictEqual(result.first, copiedObject);
assert.deepStrictEqual(result.first, copiedObject);
assert.notStrictEqual(result.list, copiedArray);
assert.deepStrictEqual(result.list, copiedArray);
assert.strictEqual(result.list[1], copiedArray[1]);
assert.strictEqual(result.nil, null);
assert.strictEqual(result.count, 7);
assert.deepStrictEqual(source, {
  first: { nested: 2 },
  live: { state: 1 },
  list: [1, { deep: true }],
  nil: null,
  count: 7,
  text: 'x'
});
assert.deepStrictEqual(liveKeys, ['live']);
result.first.nested = 99;
result.list.push(3);
assert.strictEqual(source.first.nested, 2);
assert.strictEqual(source.list.length, 2);
result.live.state = 4;
assert.strictEqual(source.live.state, 4);

assert.deepStrictEqual(projectFields({}, []), {});
const allLiveArray = [1, 2];
const allLiveObject = { a: 1 };
const allLive = projectFields({ a: allLiveArray, b: allLiveObject }, ['a', 'b']);
assert.strictEqual(allLive.a, allLiveArray);
assert.strictEqual(allLive.b, allLiveObject);

for (const invalidSource of [null, [], 1, 'x', undefined]) {
  assert.throws(() => projectFields(invalidSource, []), TypeError);
}
assert.throws(() => projectFields({}, null), TypeError);
assert.throws(() => projectFields({ a: 1 }, [1]), TypeError);
assert.throws(() => projectFields({ a: 1 }, ['missing']), TypeError);
assert.throws(() => projectFields({ a: 1 }, ['a', 'a']), RangeError);
const hidden = {};
Object.defineProperty(hidden, 'secret', { value: 1, enumerable: false });
assert.throws(() => projectFields(hidden, ['secret']), TypeError);

